def evaluate(expr: str) -> int:
    def parse_expression(tokens, pos):
        # Handle + and -
        result, pos = parse_term(tokens, pos)
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right, pos = parse_term(tokens, pos)
            if op == '+':
                result += right
            else:
                result -= right
        return result, pos

    def parse_term(tokens, pos):
        # Handle * and /
        result, pos = parse_factor(tokens, pos)
        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            right, pos = parse_factor(tokens, pos)
            if op == '*':
                result *= right
            else:
                # Integer division truncating toward zero
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                # Python's // truncates toward negative infinity, so we need to adjust
                if (result < 0) != (right < 0):
                    result = -((-result) // right)
                else:
                    result = result // right
        return result, pos

    def parse_factor(tokens, pos):
        # Handle numbers and parentheses
        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")
        if tokens[pos] == '(':
            pos += 1
            result, pos = parse_expression(tokens, pos)
            if pos >= len(tokens) or tokens[pos] != ')':
                raise ValueError("Expected closing parenthesis")
            pos += 1
            return result, pos
        else:
            # It should be a number
            num_str = tokens[pos]
            pos += 1
            return int(num_str), pos

    # Tokenize
    tokens = []
    i = 0
    while i < len(expr):
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(expr[i:j])
            i = j
        elif ch in '+-*/()':
            tokens.append(ch)
            i += 1
        else:
            raise ValueError(f"Unexpected character: {ch}")

    if not tokens:
        return 0

    result, pos = parse_expression(tokens, 0)
    if pos != len(tokens):
        raise ValueError("Unexpected token at end")
    return result
