def count_islands(grid: list[str]) -> int:
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    # Convert to a mutable 2D list
    board = [[c for c in row] for row in grid]

    def dfs(r: int, c: int) -> None:
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return
        if board[r][c] != '1':
            return
        board[r][c] = '0'
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)

    count = 0
    for r in range(rows):
        for c in range(cols):
            if board[r][c] == '1':
                count += 1
                dfs(r, c)

    return count
