def calc(expr: str) -> int:
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c}")

    # Parser using recursive descent
    # Precedence (low to high):
    # 1. + - (left-associative)
    # 2. * / (left-associative)
    # 3. unary minus
    # 4. ^ (right-associative)
    # 5. primary (numbers, parentheses)

    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        # expr := term (('+' | '-') term)*
        result = parse_term()
        while peek() is not None and peek()[0] in ('+', '-'):
            op = consume()[0]
            right = parse_term()
            if op == '+':
                result += right
            else:
                result -= right
        return result

    def parse_term():
        # term := unary (('*' | '/') unary)*
        result = parse_unary()
        while peek() is not None and peek()[0] in ('*', '/'):
            op = consume()[0]
            right = parse_unary()
            if op == '*':
                result *= right
            else:
                # Integer division truncating toward zero
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                # Python's // truncates toward negative infinity, so we need to adjust
                q = abs(result) // abs(right)
                if (result < 0) != (right < 0):
                    q = -q
                result = q
        return result

    def parse_unary():
        # unary := '-' unary | power
        if peek() is not None and peek()[0] == '-':
            consume()
            return -parse_unary()
        return parse_power()

    def parse_power():
        # power := primary ('^' power)?  (right-associative)
        base = parse_primary()
        if peek() is not None and peek()[0] == '^':
            consume()
            exp = parse_power()  # right-associative
            return int(base ** exp)
        return base

    def parse_primary():
        # primary := number | '(' expr ')'
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok[0] == 'num':
            consume()
            return tok[1]
        if tok[0] == '(':
            consume()
            result = parse_expr()
            if peek() is None or peek()[0] != ')':
                raise ValueError("Expected closing parenthesis")
            consume()
            return result
        raise ValueError(f"Unexpected token: {tok}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected tokens remaining")
    return result
