def flatten_json(obj: dict) -> dict:
    result = {}

    def _flatten(current, path):
        if isinstance(current, dict):
            if not current:
                if path:
                    result[path] = current
            else:
                for key, value in current.items():
                    new_path = f"{path}.{key}" if path else str(key)
                    _flatten(value, new_path)
        elif isinstance(current, list):
            if not current:
                if path:
                    result[path] = current
            else:
                for index, value in enumerate(current):
                    new_path = f"{path}.{index}" if path else str(index)
                    _flatten(value, new_path)
        else:
            if path:
                result[path] = current

    _flatten(obj, "")
    return result
