import re


def glob_match(name: str, pattern: str) -> bool:
    """Match the whole name against a shell-style pattern, case-sensitively."""
    # Convert the glob pattern to a regular expression
    i = 0
    n = len(pattern)
    regex_parts = []

    while i < n:
        c = pattern[i]
        if c == '*':
            regex_parts.append('.*')
            i += 1
        elif c == '?':
            regex_parts.append('.')
            i += 1
        elif c == '[':
            # Find the closing bracket
            j = i + 1
            negated = False
            if j < n and pattern[j] == '!':
                negated = True
                j += 1
            # Collect characters until closing bracket
            chars = []
            while j < n and pattern[j] != ']':
                # Check for range
                if j + 2 < n and pattern[j + 1] == '-':
                    start = pattern[j]
                    end = pattern[j + 2]
                    # Add all characters in the range
                    for code in range(ord(start), ord(end) + 1):
                        chars.append(chr(code))
                    j += 3
                else:
                    chars.append(pattern[j])
                    j += 1
            if j >= n:
                # No closing bracket, treat '[' as literal
                regex_parts.append(re.escape('['))
                i += 1
            else:
                # j is at the position of ']'
                if not chars:
                    # Empty set, match nothing
                    regex_parts.append(r'(?!.)')
                else:
                    # Escape special regex characters in the set
                    escaped_chars = []
                    for ch in chars:
                        if ch in r'\^$.|?*+()[]{}':
                            escaped_chars.append(re.escape(ch))
                        else:
                            escaped_chars.append(ch)
                    char_class = ''.join(escaped_chars)
                    if negated:
                        regex_parts.append(f'[^{char_class}]')
                    else:
                        regex_parts.append(f'[{char_class}]')
                i = j + 1
        else:
            regex_parts.append(re.escape(c))
            i += 1

    regex = ''.join(regex_parts)
    return re.fullmatch(regex, name) is not None
